-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.druid.balance.Name"] = "平衡"
L["rm.era.druid.balance.Description"] = "平衡，适用于 1 至 60 级，也是德鲁伊在获得天赋前或没有其他内置循环适用时的默认循环。学会星火术后以它作为填充（学会前为愤怒，自然之赐触发时优先星火术），法力值高于 30% 时对能存活较久的目标保持月火术和虫群，三个或更多敌人攻击你时使用飓风，组队时使用精灵之火，移动时使用瞬发法术，法力耗尽时近战。猎豹或熊形态下改为提供野性战斗的建议。提醒：野性印记、单刷时的荆棘术、清晰预兆、没有任何形态时的枭兽形态、激活、自然之握。星火术降级施法、定身和目标选择由你自己掌控。"
L["rm.era.druid.balance.icyveins.Name"] = "平衡（Icy Veins）"
L["rm.era.druid.balance.icyveins.Description"] = "Icy Veins 针对有 16 个减益效果上限的服务器的团队副本列表，是推荐的平衡内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。只用星火术，不用月火术或虫群，三个或更多敌人攻击你时使用飓风，仅在学会星火术之前使用愤怒。提醒与推荐的内置循环相同。"
L["rm.era.druid.feral.Name"] = "野性战斗"
L["rm.era.druid.feral.Description"] = "野性战斗是你的主天赋树时，10 级起的猎豹和熊；由你的形态决定使用哪一种。猎豹：潜行起手，保持精灵之火（野性），节能施法用于撕碎，四个连击点起使用终结技（学会凶猛撕咬之前以及团队副本之外的长时间战斗中用撕扯，能量低于 63 时用凶猛撕咬），团队副本之外使用扫击，在目标背后使用撕碎，目标正在攻击你时使用爪击，激怒 5/5 且法力有余时，若能量远远不足则变身回能（再次进入猎豹形态）。熊：怒气匮乏时使用狂怒，对怪群和精英使用挫志咆哮（除非已有战士的挫志怒吼），两个或更多敌人以及怒气有余时使用挥击，否则使用精灵之火（野性）。施法者形态：变形。提醒：每次挥击都用槌击、拉怪前的猛虎之怒、手动群体打击者、激活、狂暴回复。站位由你自己掌控。"
L["rm.era.druid.feral.warcrafttavern.Name"] = "野性战斗（Warcraft Tavern，撕扯和撕咬）"
L["rm.era.druid.feral.warcrafttavern.Description"] = "Warcraft Tavern 的变身回能列表，是推荐的野性内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。只要撕扯不在，就在五个连击点时使用撕扯，团队副本中也是如此，然后能量低于 63 时从四个连击点起使用凶猛撕咬，在目标背后使用撕碎，能量远远不足时变身回能。熊和提醒与推荐的内置循环相同。"
L["rm.era.druid.feral.warcrafttavern.casual.Name"] = "野性战斗（Warcraft Tavern，不变身回能）"
L["rm.era.druid.feral.warcrafttavern.casual.Description"] = "Warcraft Tavern 不含变身回能的列表，是推荐的野性内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。用撕碎攒到五个连击点（在正面时用爪击），然后对能存活的目标使用撕扯、猛虎之怒、凶猛撕咬；否则等待能量。熊和提醒与推荐的内置循环相同。"
L["rm.era.druid.feral.wowhead.Name"] = "野性战斗（Wowhead 团队熊）"
L["rm.era.druid.feral.wowhead.Description"] = "推荐的野性内置循环中的猎豹，配合 Wowhead 的装备成型团队熊：每次挥击都用槌击（对怪群切换目标施放槌击由你自己操作），仅在多出 60 点怒气时使用挥击，否则使用精灵之火（野性），战斗中不使用挫志咆哮和狂怒。它是推荐的野性内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.era.druid.restoration.Name"] = "恢复"
L["rm.era.druid.restoration.Description"] = "恢复是你的主天赋树时，10 级起的恢复。治疗你当前的友方目标：自然迅捷后使用治疗之触，目标带有你的持续治疗效果且低于 40% 时使用迅捷治愈，保持回春术和愈合滚动，拥有强化愈合时以愈合作为主要治疗，低于 45% 或自然之赐触发时使用最高等级治疗之触，否则使用 4 级治疗之触。敌对目标时：月火术、虫群和愤怒。猎豹或熊形态下不提供建议。提醒：野性印记、清晰预兆、自然迅捷、宁静、激活、复生、驱除中毒和诅咒。治疗谁由你自己掌控。"
L["rm.era.druid.restoration.warcrafttavern.Name"] = "恢复（Warcraft Tavern）"
L["rm.era.druid.restoration.warcrafttavern.Description"] = "Warcraft Tavern 的伤害分级治疗，是推荐的恢复内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。针对你的友方目标，伤害较低时不维持持续治疗效果：低于 40% 时使用迅捷治愈，低于 50% 时使用 5 级愈合，低于 75% 时使用回春术和 3 级愈合，自然之赐触发时使用最高等级治疗之触，低于 90% 时使用 3 级治疗之触。提醒与推荐的内置循环相同。"
L["rm.forever.druid.balance.Name"] = "平衡"
L["rm.forever.druid.balance.Description"] = "平衡，适用于 1 至 60 级，也是没有其他内置循环适用时所有永久服德鲁伊的默认循环（1–9 级、未点天赋的施法者、单刷的恢复德鲁伊）。以愤怒拉怪；移动时刷新月火术、虫群，组队时还有精灵之火。三个或更多敌人与你交战时使用飓风，然后是你自己的月火术和虫群，日月之蚀充能或节能施法期间使用星火术，以及愤怒；负担不起愤怒时让你进行近战。在永久服上生命值和法力值对插件隐藏，因此治疗自己和判断目标是否值得上持续伤害由你自己决定。提醒：野性印记、单刷时的荆棘术、枭兽形态、单刷时拉怪前的回春术、怪物贴身时的自然之握、单刷时战斗中激活一就绪就使用。形态切换、控制、树皮术和目标选择由你自己掌控。基于 30 级测试版指南制作；31–60 级的步骤依据职业设计，尚未经过测试。"
L["rm.forever.druid.balance.tavern.Name"] = "平衡，多目标持续伤害（Warcraft Tavern）"
L["rm.forever.druid.balance.tavern.Description"] = "Warcraft Tavern 的多目标持续伤害升级打法，是推荐的平衡内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。以愤怒拉怪，保持目标身上你自己的月火术和虫群，两者都生效且另有敌人与你交战时用纠缠根须定住它，然后是愤怒。不使用星火术（此流派不点日月之蚀）。切换到下一个敌人由你决定。提醒：野性印记、单刷时的荆棘术。"
L["rm.forever.druid.feral.Name"] = "野性，猎豹和熊"
L["rm.forever.druid.feral.Description"] = "猎豹和熊合并为一个内置循环，按你的形态选择；当野性成为你的主要天赋树（或已点出 11 点），或你变为猎豹或熊形态时，就由它接管。猎豹：潜伏状态下使用毁灭或撕碎，精灵之火，四个连击点时使用撕扯，撕扯生效后使用凶猛撕咬，扫击，然后在目标未面对你时使用撕碎（否则使用爪击）。熊：远距离使用精灵之火和野性冲锋，组队或面对两个敌人时使用挫志咆哮，原始撕咬，三个或更多敌人时使用挥击，割伤，挥击。人形态下会建议猎豹形态（学会猎豹前为熊形态）。提醒：熊形态下负担得起时就使用槌击、狂怒、大规模拉怪或面对精英时的狂暴、单刷时的激活、野性印记、荆棘术。在永久服上生命值、能量、怒气和法力值对插件隐藏，因此能量转换、狂暴回复和治疗自己由你自己决定。嘲讽、打断和站位由你自己掌控。"
L["rm.forever.druid.restoration.Name"] = "恢复"
L["rm.forever.druid.restoration.Description"] = "依据 Warcraft Tavern 的团队治疗，当恢复是你的主要天赋树且已点出 11 点后生效。治疗你当前的友方目标：对带有你的持续治疗效果的目标使用迅捷治愈，野性成长，缺失时使用愈合和回春术，治疗之触。在永久服上生命值和法力值对插件隐藏，因此你选中的目标是判断谁需要治疗的唯一依据。目标为敌对时：月火术、虫群、愤怒。提醒：战斗中的激活、战斗中对友方目标使用自然迅捷、解除诅咒和驱毒术、野性印记；宁静由你自己掌控。治疗谁和法术等级由你决定；单刷的恢复德鲁伊使用平衡内置循环。"
L["rm.forever.druid.restoration.icyveins.Name"] = "恢复，持续治疗优先（Icy Veins）"
L["rm.forever.druid.restoration.icyveins.Description"] = "Icy Veins 的持续治疗优先治疗法，是推荐的恢复内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。对你的友方目标：回春术，缺失时使用愈合，仅在两个持续治疗效果都生效时使用治疗之触，对带持续治疗的目标使用迅捷治愈，然后是野性成长（永久服中生命值是隐藏的，因此由你选中的目标决定治疗谁）。激活冷却完毕即用。其余提醒和敌对目标列表与恢复内置循环相同。"
L["rm.mop.druid.balance.Name"] = "推荐"
L["rm.mop.druid.balance.Description"] = "推荐平衡专精从 10 级起使用，依据 Wowhead 的第 5 阶段列表和 模拟器。保持月火术和阳炎术，并在对应的日月之蚀期间刷新它们，月蚀期间施放星辰坠落，坠星触发时以及冷却完毕时使用星涌术，五个敌人时在日蚀中使用飓风、在月蚀中使用星界风暴，月蚀期间及之后使用星火术，日蚀期间及之后使用愤怒。Rotation Master 无法读取蚀能，因此在两次日月之蚀之间，如果你最近三次施法中有星火术就继续施放星火术，否则施放愤怒。提醒：野性印记、枭兽形态、日月之蚀开始时使用化身、结束时使用超凡之盟（对精英或长时间战斗）、自然的守护、自然之力、为塞纳留斯的梦境使用自然迅捷、激活、日光术、生命值低时使用树皮术和甘霖。野性蘑菇的放置由你手动处理；野性蘑菇：引爆的提醒默认关闭。你施法、旅行、处于猎豹或熊形态，或没有选中敌人时它会暂停。"
L["rm.mop.druid.feral.Name"] = "推荐"
L["rm.mop.druid.feral.Description"] = "推荐野性专精从 10 级起使用，依据 模拟器 和 Wowhead 的第 5 阶段列表。让你进入猎豹形态，从潜行中以野蛮咆哮和毁灭开场，保持野蛮咆哮，拥有塞纳留斯的梦境时在四或五个连击点利用掠食者的迅捷施放治疗之触，五个连击点时使用割裂（目标生命值低于 25% 时由凶猛撕咬刷新），割裂和野蛮咆哮都还剩六秒时在五个连击点使用凶猛撕咬，斜掠，节能施法触发时使用痛击，节能施法或狂暴期间且目标没有攻击你时使用撕碎（Rotation Master 无法判断你是否在目标背后），以及裂伤；四个敌人时使用痛击和横扫。熊形态下提供一个简短的坦克列表。提醒：能量低于 35 时使用猛虎之怒，对精英或长时间战斗配合它使用狂暴，化身，自然之力，自然的守护，迎头痛击，生命值低时使用生存本能和树皮术，野性印记。熊形态穿插、愤怒穿插以及野性之心由你手动处理。"
L["rm.mop.druid.feral.icyveins.Name"] = "撕咬仅用于斩杀阶段（Icy Veins）"
L["rm.mop.druid.feral.icyveins.Description"] = "Icy Veins 的野性顺序（Wowhead 的撕咬规则与之一致），作为推荐野性内置循环的替代：启用它并禁用那个，或提高它的优先级。开场、野蛮咆哮、治疗之触和范围伤害相同，但目标生命值高于 25% 时连击点只用于割裂和野蛮咆哮：凶猛撕咬仅在斩杀阶段用于刷新割裂（或在学会割裂之前消耗五个连击点）。斜掠在剩余两秒时刷新，痛击仅在节能施法触发时使用，狂暴会等到 90 点能量且猛虎之怒至少还有 15 秒才就绪时使用。"
L["rm.mop.druid.guardian.Name"] = "推荐"
L["rm.mop.druid.guardian.Description"] = "推荐守护坦克从 10 级起使用，依据 模拟器 和 Wowhead 的第 5 阶段列表。让你进入熊形态，从远处用精灵之火或用裂伤拉怪，对精英用痛击保持虚弱打击、用精灵之火保持破甲，受伤时使用塞纳留斯的梦境触发的治疗之触，裂伤冷却完毕即用，三个敌人时使用痛击和横扫，然后是割伤、痛击和精灵之火。猎豹形态下（野性之心）提供一个简短的伤害列表。提醒：野蛮防御未生效时使用、用激怒获取怒气、生命值低或怒气溢出时使用狂暴回复、怒气高于 90 或尖牙与利爪触发时使用重殴、目标攻击你时使用树皮术、生命值低时使用生存本能、两个敌人或首领时使用狂暴和化身、自然之力、自然的守护、塞纳里奥结界、迎头痛击、野性印记。嘲讽和乌索克之力由你手动处理（两者的提醒默认关闭）。"
L["rm.mop.druid.restoration.Name"] = "推荐"
L["rm.mop.druid.restoration.Description"] = "推荐恢复专精从 10 级起使用，依据 Wowhead 的第 5 阶段队伍治疗。治疗你当前的友方目标，没有目标时治疗你自己；治疗谁由你决定。目标带有你的持续治疗效果且生命值较低、相生已消失，或拥有丛林之魂时为接野性成长，使用迅捷治愈；附近有三人受伤时使用野性成长；自然迅捷后使用瞬发治疗之触；节能施法触发或目标濒死时使用愈合；回春术；然后站立不动时使用治疗之触和滋养。可攻击的目标会获得月火术和愤怒。提醒：对你的焦点目标保持生命绽放层数和铁木树皮（请将坦克设为焦点目标）、队伍受到伤害时使用野性蘑菇：绽放、自然之力、化身、自然的守护、自然迅捷、激活、自然之愈、塞纳里奥结界、树皮术、野性印记。野性蘑菇放置、宁静和源生的提醒默认关闭。"
L["rm.mop.druid.restoration.wowhead.Name"] = "坦克治疗（Wowhead）"
L["rm.mop.druid.restoration.wowhead.Description"] = "Wowhead 的单目标坦克治疗顺序，在你被指派治疗坦克时作为推荐恢复内置循环的替代：启用它并禁用那个，或提高它的优先级。保持选中坦克：它会在坦克身上保持三层生命绽放和回春术，伤害较重时使用愈合，伤害较轻时使用滋养，生命绽放和回春术都在滚动且坦克低于一半时使用治疗之触，并用迅捷治愈让坦克保持满血。提醒与推荐的内置循环相同。"
L["rm.mop.druid.unspecialized.Name"] = "选择专精前"
L["rm.mop.druid.unspecialized.Description"] = "适用于 1 至 9 级，或尚未选择专精的德鲁伊；选择专精后由专精内置循环接管。猎豹形态下保持斜掠，在五个连击点（对濒死目标为两个）时使用凶猛撕咬，并用裂伤攒点；熊形态下使用裂伤和重殴。其他情况下以愤怒拉怪，对能存活较久的目标保持月火术，施放愤怒（移动时用月火术），独自一人且生命值低于一半时建议对自己施放回春术。你施法、旅行或没有选中敌人时它会暂停。"
L["rm.retail.druid.balance.Name"] = "暴雪战斗辅助"
L["rm.retail.druid.balance.Description"] = "推荐平衡专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的超凡之盟（或化身）、对可打断的施法使用日光术、拉怪间隙的枭兽形态和野性印记，以及你的种族冷却技能和战斗中一就绪就使用的树皮术。敌人的施法在战斗中是隐藏的，因此日光术只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用树皮术由你自己决定。"
L["rm.retail.druid.balance.guide.Name"] = "参考（Icy Veins、SimulationCraft 和 Wowhead）"
L["rm.retail.druid.balance.guide.Description"] = "仅供参考，默认关闭：指南中的平衡优先级。在至暗之夜的战斗中，你的持续伤害效果、日蚀和触发效果对插件隐藏，因此它无法在战斗中运行；可以阅读它，或复制后自行试验。星界能量在正式服中是隐藏的，所以星涌术按其消耗施放，而不是在溢出之前施放。以枭兽形态和愤怒拉怪。阳炎术和月火术缺失或即将消失时补上；两种日蚀都未生效时触发日蚀（三个或更多敌人时触发月蚀，否则触发日蚀）；织星者的经纱、浩瀚之触触发或面对成群敌人时使用星辰坠落；织星者的纬纱或浩瀚之触触发时使用星涌术；新月、半月和满月；日蚀期间使用野性蘑菇；只要负担得起就使用星涌术；月蚀期间或面对成群敌人时使用星火术，否则使用愤怒。提醒：超凡之盟或化身、在日蚀之前使用艾露恩之怒和自然之力、超凡之盟期间使用万灵之召、日光术，以及功能性提醒。"
L["rm.retail.druid.feral.Name"] = "暴雪战斗辅助"
L["rm.retail.druid.feral.Description"] = "推荐野性专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的狂暴（或化身）、对可打断的施法使用迎头痛击、战斗中一就绪就使用的生存本能、树皮术和你的种族冷却技能，以及拉怪间隙的猎豹形态和野性印记。敌人的施法在战斗中是隐藏的，因此打断提醒只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此何时使用防御技能由你自己决定。"
L["rm.retail.druid.feral.guide.Name"] = "参考（Icy Veins 和 SimulationCraft）"
L["rm.retail.druid.feral.guide.Description"] = "仅供参考，默认关闭：指南中的野性优先级。流血效果和触发效果在至暗之夜的战斗中是隐藏的（连击点数不是），因此它无法在战斗中运行；能量在正式服中是隐藏的。以猎豹形态、潜行和斜掠开场。啃噬；顶级捕食者的渴望触发时使用凶猛撕咬；五个连击点数时：两个或更多敌人使用原始之怒，割裂缺失或只剩最后几秒时使用割裂，否则使用凶猛撕咬，宁可等待能量也不要攒超过五点；不足五点时：斜掠缺失或即将消失时使用斜掠，月之灵的月火术，三个或更多敌人时使用横扫，撕碎。提醒：猛虎之怒战斗中一就绪就使用、猛虎之怒期间使用狂暴或化身以及野性狂乱或怒意狂乱（连击点数不超过两点时）、猛虎之怒和狂暴期间且割裂生效时使用万灵之召、迎头痛击、生存本能，以及功能性提醒。流血效果的快照时机仍由你自己掌控。"
L["rm.retail.druid.guardian.Name"] = "暴雪战斗辅助"
L["rm.retail.druid.guardian.Description"] = "推荐守护专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；战斗辅助只考虑伤害输出。同时提醒它留给你处理的部分：战斗中的狂暴（或化身）和万灵之召、战斗中一就绪就使用的铁鬃、狂暴回复、生存本能、树皮术和你的种族冷却技能、对可打断的施法使用迎头痛击，以及拉怪间隙的熊形态和野性印记。敌人的施法在战斗中是隐藏的，因此迎头痛击只在游戏显示它们的场合亮起；生命值和怒气在正式服中是隐藏的，因此何时使用防御技能由你自己决定，铁鬃也无法等待怒气达到阈值。"
L["rm.retail.druid.guardian.guide.Name"] = "参考（Icy Veins 和 Wowhead）"
L["rm.retail.druid.guardian.guide.Description"] = "仅供参考，默认关闭：指南中的守护优先级。减益效果和触发效果在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行；怒气和生命值在正式服中是隐藏的，所以怒气达到 80 时的摧折和重殴消耗由你自己掌控。痛击和裂伤冷却好就用，单体时使用赤红之月，月火术缺失或星河守护者触发时使用月火术，横扫。战斗中一就绪就使用的提醒：铁鬃、狂暴回复、生存本能；拉怪间隙的熊形态；狂暴或化身、明月普照、万灵之召、野性之心、迎头痛击，以及功能性提醒。"
L["rm.retail.druid.guardian.simc.Name"] = "防御型参考（SimulationCraft）"
L["rm.retail.druid.guardian.simc.Description"] = "仅供参考，默认关闭：SimulationCraft 的守护列表，优先把怒气花在铁鬃上。战斗数据被隐藏，因此它无法在至暗之夜的战斗中运行；怒气在正式服中是隐藏的，所以其怒气阈值被省略了。狂暴期间使用铁鬃；痛击缺失、即将消失或少于三层时使用痛击；血污毛皮触发时使用重殴；三个或更多敌人时使用痛击；赤红之月造成伤害期间使用裂伤；赤红之月；裂伤；痛击；月火术；横扫。其中穿插猎豹形态的部分未包含在内。提醒：熊形态、狂暴回复、生存本能、狂暴或化身、明月普照、万灵之召、迎头痛击，以及功能性提醒。"
L["rm.retail.druid.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.druid.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是德鲁伊的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有德鲁伊内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.druid.restoration.Name"] = "暴雪战斗辅助，含维持施法"
L["rm.retail.druid.restoration.Description"] = "推荐恢复专精使用。选中敌人时，它会高亮暴雪战斗辅助的建议，也就是暴雪为恢复专精设计的猎豹形态或人形态伤害列表。否则，它会对你的友方目标（或你自己）建议 Icy Veins 的维持性施法：生命绽放、战斗中使用百花齐放、对带有回春术的目标使用迅捷治愈、组队战斗中使用野性成长、节能施法触发或丰饶达到五层时使用愈合、缺失时使用回春术。生命值和法力值在正式服中是隐藏的，因此这些建议依据你选中的目标，而不是依据谁受伤有多重；在至暗之夜的战斗中，你的持续治疗效果是隐藏的，因此读取它们的步骤在战斗中会等待。治疗谁以及所有治疗冷却技能都由你决定。提醒：战斗中一就绪就使用的激活、树皮术和你的种族冷却技能，拉怪间隙的野性印记。"
L["rm.sod.druid.balance.Name"] = "平衡（探索赛季）"
L["rm.sod.druid.balance.Description"] = "探索赛季的平衡，适用于 1 至 60 级，也是没有其他探索赛季内置循环适用时所有德鲁伊的默认循环。星涌术的增益效果消失时使用星涌术，对能存活较久的目标使用阳炎术和月火术，仅在星涌术或月蚀强化时使用星火术，愤怒作为填充，六个或更多敌人时使用飓风（铭刻了烈风时为四个），仅在移动时使用虫群。符文在你铭刻后即会使用。猎豹或熊形态下改为提供野性战斗的建议。提醒：枭兽形态、星辰坠落、对濒死的友方使用瞬发治疗之触、驱除诅咒和中毒、队伍受伤时使用野性成长、激活。把持续伤害效果扩散到其他目标由你自己掌控。"
L["rm.sod.druid.balance.icyveins.Name"] = "平衡（探索赛季，Icy Veins）"
L["rm.sod.druid.balance.icyveins.Description"] = "Icy Veins 的探索赛季列表，是推荐的探索赛季平衡内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。星涌术冷却完毕即用，四个或更多敌人时使用飓风（为了烈风），星涌术强化时使用星火术，同时保持月火术、阳炎术和虫群，愤怒作为填充。提醒与推荐的内置循环相同。"
L["rm.sod.druid.balance.wowhead.Name"] = "平衡（探索赛季，Wowhead）"
L["rm.sod.druid.balance.wowhead.Description"] = "Wowhead 的第 8 阶段列表，是推荐的探索赛季平衡内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。以愤怒开场，星涌术冷却完毕即用，六个或更多敌人时使用飓风，仅在移动时使用虫群，保持阳炎术和月火术，铭刻了艾露恩之火来延长阳炎术时，在你的阳炎术剩余不到 5 秒时使用愤怒，月蚀时使用星火术，否则使用愤怒。提醒与推荐的内置循环相同。"
L["rm.sod.druid.feral.Name"] = "野性战斗猎豹（探索赛季）"
L["rm.sod.druid.feral.Description"] = "探索赛季的猎豹，铭刻了野蛮咆哮时选用（或野性战斗是你的主天赋树且没有铭刻其他腿部符文时）。没有精灵之火时使用精灵之火（野性），野蛮咆哮，四个或更多敌人时使用横扫（猎豹），保持割碎减益效果，节能施法用于撕碎，五个连击点且野蛮咆哮还剩 8 秒时使用撕扯，扫击，在目标背后使用撕碎，在正面时使用割碎，激怒 5/5 时变身回能，最后刷新精灵之火。熊形态下改为提供坦克建议。提醒：能量不高于 60 时使用猛虎之怒、配合猛虎之怒使用狂暴、槌击、激活。站位由你自己掌控。"
L["rm.sod.druid.restoration.Name"] = "恢复（探索赛季）"
L["rm.sod.druid.restoration.Description"] = "探索赛季的恢复，铭刻了生命绽放时选用（或恢复是你的主天赋树且没有铭刻其他腿部符文时）。治疗你当前的友方目标：自然迅捷或怒风之怒后使用瞬发治疗之触，附近有两人或更多受伤时使用野性成长，对带有你的持续治疗效果的目标使用迅捷治愈以触发百花齐放或在低于 40% 时使用，保持三层生命绽放并在剩余一秒时刷新，回春术，低于 60% 时使用愈合，滋养，4 级治疗之触。敌对目标时：阳炎术、月火术、愤怒。提醒：压力大时使用生命之树和生存本能、自然迅捷、宁静、激活、复生、起死回生、驱散。治疗谁由你自己掌控。"
L["rm.sod.druid.tank.Name"] = "熊坦（探索赛季）"
L["rm.sod.druid.tank.Description"] = "探索赛季的熊坦，铭刻了割伤时选用。用精灵之火（野性）或阳炎术（熊）远程拉怪，割伤消失前续上，割碎冷却完毕即用，割伤，挥击；三个或更多敌人时在狂暴期间使用割碎和挥击。猎豹形态下执行猎豹列表用于副坦；施法者形态下会变为熊形态。提醒：30 点怒气时使用槌击、狂暴、生命值低时使用生存本能、狂暴回复和树皮术，拉怪间隙使用狂怒，对精英使用挫志咆哮。嘲讽和目标选择由你自己掌控。"
L["rm.sod.druid.tank.simulator.Name"] = "熊坦（探索赛季，模拟器 猎豹穿插）"
L["rm.sod.druid.tank.simulator.Description"] = "默认关闭；适合装备同样提供野蛮咆哮的高手。模拟器 第 7 阶段的猎豹穿插：你的扫击消失时从熊形态切换到猎豹形态，保持野蛮咆哮和扫击（用猛虎之怒和割碎攒点），然后回到巨熊形态并执行坦克列表。提醒与推荐的坦克内置循环相同。"
L["rm.tbc.druid.balance.Name"] = "平衡"
L["rm.tbc.druid.balance.Description"] = "施法型平衡，适用于 1 至 70 级，也是没有其他内置循环适用时所有德鲁伊的默认循环。以星火术拉怪（20 级前为愤怒），移动时使用虫群和月火术，组队时使用精灵之火，三个或更多敌人时使用飓风，月火术消失且你有 30% 法力值时补上月火术，自然之赐触发时使用星火术，对近战范围内的目标使用愤怒，然后是星火术（学会前为愤怒）。猎豹、熊或旅行形态下不提供建议。提醒：野性印记、单刷时的荆棘术、清晰预兆、枭兽形态、长时间战斗中的自然之力、法力值低时的激活。"
L["rm.tbc.druid.feral.icyveins.Name"] = "野性（Icy Veins、Warcraft Tavern & 模拟器）"
L["rm.tbc.druid.feral.icyveins.Description"] = "野性天赋树的猎豹和熊，跟随你当前的形态。猎豹：潜行起手（突袭、毁灭或撕碎），精灵之火（野性），对能存活的目标在四个连击点时使用撕扯，两次撕扯之间没有节能施法时使用凶猛撕咬，保持裂伤，在目标背后使用撕碎，目标正在攻击你时使用裂伤/爪击。熊：精灵之火，在割伤消失前续上，除非已有战士的挫志怒吼否则使用挫志咆哮，怪群使用横扫，然后裂伤、叠满五层割伤、横扫。人形态下会建议猎豹（或熊）形态。提醒：野性印记、荆棘术、清晰预兆、怒气有余时的重殴、拉怪前的猛虎之怒、狂暴回复。变身回能（powershifting）是默认关闭的可选步骤（需要一个变身回能宏）。"
L["rm.tbc.druid.feral.wowhead.Name"] = "野性（Wowhead）"
L["rm.tbc.druid.feral.wowhead.Description"] = "Wowhead 的野性，是推荐的 Icy Veins 野性内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。撕扯不在时于四个连击点补上，凶猛撕咬仅用于即将死亡的目标（不穿插撕咬）；熊形态把空闲的公共冷却用在割伤上，再使用横扫。猎豹法力不足时使用激活。其余与 Icy Veins 版本相同。"
L["rm.tbc.druid.restoration.Name"] = "恢复"
L["rm.tbc.druid.restoration.Description"] = "恢复天赋树的治疗，作用于你的友方目标（或你自己）：自然迅捷后使用治疗之触，对带有你的回春术或愈合的濒死目标使用迅捷治愈，战斗中保持三层生命绽放滚动，缺少时补上回春术和愈合，然后在生命之树形态下使用愈合，不在该形态时使用治疗之触。目标为敌对时使用月火术和愤怒进行单刷。提醒：野性印记、清晰预兆、生命之树、自然迅捷、宁静、激活和复生。治疗谁以及降级施法由你自己掌控。"
